func fetchToStoreV2(
	ctx context.Context,
	store storer.Storer,
	conn Conn,
	caps *V2Capabilities,
	desired map[plumbing.ReferenceName]DesiredRef,
	targetRefs map[plumbing.ReferenceName]plumbing.Hash,
	verbose bool,
) (err error) {
	wants := collectWants(desired)
	haves := SortedUniqueHashes(refValues(targetRefs))
	if len(wants) == 0 {
		return git.NoErrAlreadyUpToDate
	}

	cmdArgs := make([]string, 0, len(wants)+len(haves)+4)
	// NOTE: no "thin-pack" argument. The relayed pack must stay
	// self-contained so callers (e.g. replicate) can forward it to
	// receive-pack servers that may advertise "no-thin". See
	// planner.SupportsReplicateRelay for the matching invariant.
	cmdArgs = append(cmdArgs, "ofs-delta")
	if !verbose {
		cmdArgs = append(cmdArgs, "no-progress")
	}
	for _, h := range wants {
		cmdArgs = append(cmdArgs, "want "+h.String())
	}
	for _, h := range haves {
		cmdArgs = append(cmdArgs, "have "+h.String())
	}
	cmdArgs = append(cmdArgs, "done")

	body, err := EncodeCommand("fetch", caps.RequestCapabilities(), cmdArgs)
	if err != nil {
		return err
	}
	reader, err := PostRPCStream(ctx, conn, transport.UploadPackService, body, true, "upload-pack fetch")
	if err != nil {
		return err
	}
	defer closeJoin(reader, &err)
	return storeV2FetchPack(store, reader, verbose, conn.ProgressWriter())
}

// maxTrailingResponseBytes bounds how much closeJoin reads past the pack. Only
// a flush or response-end packet should follow it.
const maxTrailingResponseBytes = 64 << 10

// closeJoin keeps the stream's close error. On success it first drains what
// follows the pack: closing with those bytes unwritten makes ssh or the
// remote helper die on EPIPE, which would fail a fetch that stored every
// object.
func closeJoin(c io.ReadCloser, err *error) {
	if *err == nil {
		//nolint:errcheck // a read error here also surfaces from Close
		_, _ = io.CopyN(io.Discard, c, maxTrailingResponseBytes)
	}
	if cerr := c.Close(); cerr != nil {
		*err = errors.Join(*err, cerr)
	}
}

func fetchPackV2(
	ctx context.Context,
	conn Conn,
	caps *V2Capabilities,
	desired map[plumbing.ReferenceName]DesiredRef,
	targetRefs map[plumbing.ReferenceName]plumbing.Hash,
	verbose bool,
) (io.ReadCloser, error) {
	wants := collectWants(desired)
	haves := SortedUniqueHashes(refValues(targetRefs))
	if len(wants) == 0 {
		return nil, git.NoErrAlreadyUpToDate
	}

	cmdArgs := make([]string, 0, len(wants)+len(haves)+4)
