// leaseMode is ENTIRE_MIRROR_SYNC_LEASE: whether a job takes the target lease
// before it syncs (docs/design/mirror-sync-target-lease.md). enforce takes the
// lease and defers a job that finds it held.
type leaseMode string

const (
	leaseModeOff     leaseMode = "off"
	leaseModeEnforce leaseMode = "enforce"
)

// parseLeaseMode reads ENTIRE_MIRROR_SYNC_LEASE; unset means off. Any other
// value fails startup, so a typo can't silently turn leases off or on.
func parseLeaseMode(raw string) (leaseMode, error) {
	switch m := leaseMode(raw); m {
	case "":
		return leaseModeOff, nil
	case leaseModeOff, leaseModeEnforce:
		return m, nil
	}
	return "", fmt.Errorf("ENTIRE_MIRROR_SYNC_LEASE must be off or enforce, got %q", raw)
}

// leaseTimeouts are the lease timeouts the worker derives from AckWait and the
// sync timeout (design: Timeouts), so changing either input moves them along.
type leaseTimeouts struct {
	// tick paces the holder's lease read; it rides the InProgress extender.
	tick time.Duration
	// selfStop is how long a holder syncs without a successful lease read
	// before it cancels: one tick before JetStream redelivers its job and
	// another worker can take the lease over.
	selfStop time.Duration
	// requiredTTL is the shortest lease bucket TTL that cannot expire under a
	// live holder: the longest sync plus the redelivery wait.
	requiredTTL time.Duration
}

func deriveLeaseTimeouts(ackWait, syncTimeout time.Duration) leaseTimeouts {
	tick := ackWait / 3
	return leaseTimeouts{tick: tick, selfStop: ackWait - tick, requiredTTL: syncTimeout + ackWait}
}

// reason values for mirror.sync.lease.disabled: why the startup check turned
// leases off.
const (
	leaseDisabledSyncTimeout   = "sync_timeout_unset"         // ENTIRE_WORKER_SYNC_TIMEOUT <= 0
	leaseDisabledLeaseBucket   = "lease_bucket_unavailable"   // mirror_sync_leases not bound
	leaseDisabledPendingBucket = "pending_bucket_unavailable" // mirror_sync_pending not bound
	leaseDisabledLeaseTTL      = "lease_ttl_too_short"        // bucket TTL unset or below requiredTTL
)

// leaseCheckTimeout bounds the startup check, so an unresponsive JetStream
// turns leases off instead of holding up the worker.
const leaseCheckTimeout = 10 * time.Second

// leaseOpTimeout bounds each lease KV call on the job path, so an unanswered
// request costs a job seconds, not its sync budget.
const leaseOpTimeout = 5 * time.Second

// leaseConfig is the worker's lease setup after the startup check. mode is off
// unless the flag asks for leases and the check passed; the stores are bound
// whenever mode is not off.
type leaseConfig struct {
	mode     leaseMode
	timeouts leaseTimeouts
	leases   leaseStore
	pending  pendingNotes
	// pod names this worker in the leases it takes; informational.
	pod string
}

// leaseStore is the lease store as a job uses it; an interface so a test can
// fail its reads.
type leaseStore interface {
	Acquire(ctx context.Context, target string, v synclease.Lease) (uint64, error)
	Get(ctx context.Context, target string) (v synclease.Lease, rev uint64, found bool, err error)
	TakeOver(ctx context.Context, target string, v synclease.Lease, rev uint64) (uint64, error)
	Release(ctx context.Context, target string, rev uint64) error
}

// pendingNotes is the pending-note store as the worker uses it; an interface
// so a test can lose a write's reply.
type pendingNotes interface {
	Put(ctx context.Context, target, kind string, n synclease.Note) (uint64, error)
	Get(ctx context.Context, target, kind string) (synclease.NoteEntry, bool, error)
	DeleteAt(ctx context.Context, target, kind string, rev uint64) error
}

// setupLeases runs the startup check for mode. On failure the worker syncs
// without leases, like with the flag off, and reports the reason on
// mirror.sync.lease.disabled. With the flag off it touches nothing.
func setupLeases(ctx context.Context, js jetstream.JetStream, mode leaseMode, syncTimeout time.Duration, m *workerMetrics) leaseConfig {
	if mode == leaseModeOff {
		return leaseConfig{mode: leaseModeOff}
	}
	timeouts := deriveLeaseTimeouts(consumerAckWait, syncTimeout)
	ctx, cancel := context.WithTimeout(ctx, leaseCheckTimeout)
	defer cancel()
	leases, pending, reason, err := checkLeases(ctx, js, syncTimeout, timeouts)
	if reason != "" {
		slog.ErrorContext(ctx, "Sync leases disabled; syncing without them until restart",
			slog.String("requested_mode", string(mode)), slog.String("reason", reason), slog.Any("error", err))
		m.recordLeasesDisabled(ctx, reason)
		return leaseConfig{mode: leaseModeOff, timeouts: timeouts}
	}
	slog.InfoContext(ctx, "Sync leases enabled",
		slog.String("mode", string(mode)),
		slog.Duration("tick", timeouts.tick),
		slog.Duration("self_stop", timeouts.selfStop),
		slog.Duration("required_ttl", timeouts.requiredTTL))
	m.recordLeasesDisabled(ctx, "")
	pod, _ := os.Hostname() // the pod name in Kubernetes
	return leaseConfig{mode: mode, timeouts: timeouts, leases: leases, pending: pending, pod: pod}
}

// checkLeases binds both buckets and checks the sync timeout and the lease
// bucket TTL. A non-empty reason means leases must stay off; err explains it.

// succeeded.
func (c *consumer) acquireLease(ctx context.Context, msg *nats.Msg, kind gitjobs.SourceKind, target string) (held *heldLease, deferred bool) {
	// A job shutdown already canceled fails its sync at once; counting it as
	// acquire_failed would add noise on every rollout.
	if c.lease.leases == nil || ctx.Err() != nil {
		return nil, false
	}
	meta, err := msg.Metadata()
	if err != nil {
		c.acquireFailed(ctx, kind, target, err)
		return nil, false
	}
	for round := 1; ; round++ {
		v := c.newLease(kind, meta)
		rev, err := c.tryAcquire(ctx, target, v)
		if errors.Is(err, synclease.ErrHeld) {
			var ok bool
			if rev, ok, err = c.takeOverOwnLease(ctx, target, meta, v); err == nil && !ok {
				err = synclease.ErrHeld
			}
		}
		if err == nil {
			return c.newHeldLease(kind, target, v, rev, c.coveredNote(ctx, kind, target)), false
		}
		if !errors.Is(err, synclease.ErrHeld) {
			// Shutdown can cancel a later round; that is not a KV failure.
			if ctx.Err() == nil {
				c.acquireFailed(ctx, kind, target, err)
			}
			return nil, false
		}
		if err := c.putNote(ctx, msg, kind, target, meta.Sequence.Stream); err != nil {
			// The original message is the durable copy until a note exists.
			slog.ErrorContext(ctx, "Target leased by another sync and the pending note failed; naking",
				slog.String("target_ulid", target), slog.Any("error", err))
			c.metrics.recordLeaseEvent(ctx, leaseEventNoteFailed, string(kind))
			_ = msg.NakWithDelay(consumerFailureDelay)
			return nil, true
		}
		// A holder that released between the acquire and the note write has
		// already republished what it found, so nobody would see this note
		// until the rekicker sweeps it. Take the lease instead.
		if round < deferRounds && c.leaseGone(ctx, target) {
			continue
		}
		slog.InfoContext(ctx, "Target leased by another sync; deferred to a pending note",
			slog.String("target_ulid", target))
		trace.SpanFromContext(ctx).SetAttributes(attribute.Bool("entire.sync.deferred", true))
		c.metrics.recordLeaseEvent(ctx, leaseEventDeferred, string(kind))
		_ = msg.Ack()
		return nil, true
	}
}

func (c *consumer) tryAcquire(ctx context.Context, target string, v synclease.Lease) (uint64, error) {
	opCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
	defer cancel()
	return c.lease.leases.Acquire(opCtx, target, v)
}

// takeOverAttempts bounds how often takeOverOwnLease rereads a lease that
// moved but still names the job. One hold-over can land in between; more is
// churn.
const takeOverAttempts = 3

// newLease is the lease value for this job: its stream and stream sequence let
// a redelivery of the job take the lease over.
func (c *consumer) newLease(kind gitjobs.SourceKind, meta *nats.MsgMetadata) synclease.Lease {
	return synclease.Lease{
		Pod:       c.lease.pod,
		Stream:    meta.Stream,
		StreamSeq: meta.Sequence.Stream,
		Kind:      string(kind),
		StartedAt: time.Now().UTC(),
	}
}

// takeOverOwnLease takes over a held lease that names this job's own stream
// and stream sequence, at the revision it read, writes v, and returns the new
// revision. JetStream redelivered the job: its holder Naked and held the
// lease over, or stopped extending the job for AckWait. No clocks are
// compared. ok is false when the lease is another job's, or went away since
// the acquire; the caller treats it as held. A lease that moved but still
// names this job is read again: the earlier delivery may have held it over
// in between, and deferring would ack the job's own message. err is a
// failure to read or write the lease.
func (c *consumer) takeOverOwnLease(ctx context.Context, target string, meta *nats.MsgMetadata, v synclease.Lease) (rev uint64, ok bool, err error) {
	opCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
	defer cancel()
	var held synclease.Lease
	for attempt := 1; ; attempt++ {
		var heldRev uint64
		var found bool
		held, heldRev, found, err = c.lease.leases.Get(opCtx, target)
		if err != nil {
			return 0, false, err
		}
		if !found || held.Stream != meta.Stream || held.StreamSeq != meta.Sequence.Stream {
			return 0, false, nil
		}
		rev, err = c.lease.leases.TakeOver(opCtx, target, v, heldRev)
		if errors.Is(err, synclease.ErrRevisionChanged) && attempt < takeOverAttempts {
			continue
		}
		if errors.Is(err, synclease.ErrRevisionChanged) {
			return 0, false, nil
		}
		if err != nil {
			return 0, false, err
		}
		break
	}
	if !held.HeldOverAt.IsZero() {
		slog.InfoContext(ctx, "Took back the sync lease this job held over its retry",
			slog.String("target_ulid", target), slog.Uint64("delivery", meta.NumDelivered), slog.Time("held_over_at", held.HeldOverAt))
		return rev, true, nil
	}
	slog.WarnContext(ctx, "Took over the sync lease of this job's earlier delivery; its holder stopped",
		slog.String("target_ulid", target), slog.String("previous_pod", held.Pod), slog.Time("previous_started_at", held.StartedAt))
	return rev, true, nil
}

// putNote writes the note that replays msg: its subject, payload, stream
// sequence, rekick header and trace context.
func (c *consumer) putNote(ctx context.Context, msg *nats.Msg, kind gitjobs.SourceKind, target string, seq uint64) error {
	n := synclease.Note{Subject: msg.Subject, Payload: msg.Data, StreamSeq: seq, Rekick: msg.Header.Get(failindex.RekickHeader)}
	for _, h := range traceHeaders {
		if vs := msg.Header.Values(h); len(vs) > 0 {
			if n.Trace == nil {
				n.Trace = map[string]string{}
			}
			// Both list headers may be split across lines; one comma-joined
			// value means the same.
			n.Trace[h] = strings.Join(vs, ",")
		}
	}
	opCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
	defer cancel()
	_, err := c.lease.pending.Put(opCtx, target, string(kind), n)
	return err
}

// leaseGone reads the lease again after the note write. A failed read counts
// as held: the note is written, so acking loses nothing.
func (c *consumer) leaseGone(ctx context.Context, target string) bool {
	opCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
	defer cancel()
	_, _, found, err := c.lease.leases.Get(opCtx, target)
	if err != nil {
		slog.WarnContext(ctx, "Failed to read the sync lease after deferring; leaving the note",
			slog.String("target_ulid", target), slog.Any("error", err))
		return false
	}
	return !found
}

func (c *consumer) acquireFailed(ctx context.Context, kind gitjobs.SourceKind, target string, err error) {
	slog.WarnContext(ctx, "Failed to take the sync lease; syncing without it",
		slog.String("target_ulid", target), slog.Any("error", err))
	c.metrics.recordLeaseEvent(ctx, leaseEventAcquireFailed, string(kind))
}

// coveredNote reads the note of this job's own kind as it takes the lease and
// returns its revision, 0 when there is none. The sync that follows covers
// that note, but not a newer one. A failed read returns 0: release then
// republishes the note, which costs one redundant sync.
func (c *consumer) coveredNote(ctx context.Context, kind gitjobs.SourceKind, target string) uint64 {
	opCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
	defer cancel()
	// A note that won't decode is still covered: the sync is of its kind.
	e, found, err := c.lease.pending.Get(opCtx, target, string(kind))
	if err != nil && !found {
		slog.WarnContext(ctx, "Failed to read the pending note at lease time; release republishes it",
			slog.String("target_ulid", target), slog.Any("error", err))
	}
	if !found {
		return 0
	}
	return e.Revision
}

// holdOver keeps the lease for the redelivery of the holder's job, which Naks
// for a retry (design: Hold-over). It rewrites the lease at its revision,
// marked held over, which restarts the bucket TTL for the retry delay, and
// leaves every note for the release that follows the job's last attempt. The
// redelivery takes the lease back by its stream sequence, so the job keeps its
// delivery count and reaches its final attempt.
//
// A changed revision means the lease is no longer ours, as in releaseLease.
// Any other failure falls back to a release, so the target is not left
// blocked; a fresh job may then take it.
func (c *consumer) holdOver(ctx context.Context, h *heldLease) (lost bool) {
	ctx = context.WithoutCancel(ctx)
	v := h.value
	v.HeldOverAt = time.Now().UTC()
	opCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
	defer cancel()
	_, err := c.lease.leases.TakeOver(opCtx, h.target, v, h.rev)
	switch {
	case err == nil:
		slog.InfoContext(ctx, "Holding the sync lease over for this job's retry",
			slog.String("target_ulid", h.target), slog.Uint64("stream_seq", v.StreamSeq))
		trace.SpanFromContext(ctx).SetAttributes(attribute.Bool("entire.sync.lease_held_over", true))
		c.metrics.recordLeaseEvent(ctx, leaseEventHeldOver, string(h.kind))
		return false
	case errors.Is(err, synclease.ErrRevisionChanged):
		slog.WarnContext(ctx, "Sync lease taken over; stepping aside without Ack, Nak or Term",
			slog.String("target_ulid", h.target), slog.Any("error", err))
		h.lose(ctx)
		return true
	}
	slog.WarnContext(ctx, "Failed to hold the sync lease over for the retry; releasing it",
		slog.String("target_ulid", h.target), slog.Any("error", err))
	return c.releaseLease(ctx, h, 0, nil)
}

// releaseLease runs the release steps before the job's own Ack, Nak or Term
// (design: Release). covered is the revision of the own-kind note the sync
// covered, 0 for none. final, when set, is a job that failed for good: it is
// recorded after the purge and before the hand-off, and when that write
// recorded it, the own-kind note read before the purge is deleted instead of
// republished if the replay stands in for it. A newer note was written after
// the purge, behind whoever took the lease next, and is handed off as usual.
//
//  1. Delete the covered note at its revision. A newer note survives.
//  2. Purge the lease at the revision this job took it at. A changed revision
//     means the lease is no longer ours: it counts lease_lost and reports lost,
//     the purge left the new lease alone, and the new holder hands off the
//     notes. Any other failure counts lease_release_failed and leaves the notes
//     to the rekicker, as the lease may still block their jobs.
//  3. Republish the notes for the target and delete them (handOffNotes).
//
// It runs even after shutdown canceled the job: a lease left behind blocks the
// target until the bucket TTL, and its notes until the rekicker's sweep.
func (c *consumer) releaseLease(ctx context.Context, h *heldLease, covered uint64, final *finalJob) (lost bool) {
	kind, target := h.kind, h.target
	ctx = context.WithoutCancel(ctx)
	if covered != 0 {
		c.deleteNote(ctx, target, string(kind), covered)
	}
	var ownNote uint64
	if final != nil {
		ownNote = c.coveredNote(ctx, kind, target)
	}
	opCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
	defer cancel()
	err := c.lease.leases.Release(opCtx, target, h.rev)
	switch {
	case err == nil:
	case errors.Is(err, synclease.ErrRevisionChanged):
		slog.WarnContext(ctx, "Sync lease taken over; stepping aside without Ack, Nak or Term",
			slog.String("target_ulid", target), slog.Any("error", err))
		h.lose(ctx)
		return true
	default:
		slog.ErrorContext(ctx, "Failed to release the sync lease; it expires at the bucket TTL",
			slog.String("target_ulid", target), slog.Any("error", err))
		c.metrics.recordLeaseEvent(ctx, leaseEventReleaseFailed, string(kind))
		return false
	}
	var drop func(synclease.NoteEntry) bool
	if final != nil && final.record() {
		drop = func(e synclease.NoteEntry) bool {
			return e.Kind == string(kind) && e.Revision == ownNote && final.replays(e.Note)
		}
	}
	c.handOffNotes(ctx, kind, target, drop)
	return false
}

// handOffNotes reads the note of each kind for target, republishes it as a
// fresh job, then deletes it at the revision it read (design: Release, steps 3
// and 4). It runs after the purge, so a republished job can take the lease at
// once. One Get per kind, not a watch: a watch costs an ephemeral consumer on
// every release. A note that can't be read or republished stays for the
// rekicker's sweep and counts lease_release_failed, once per release, under
// the releasing job's kind; the job is still disposed. drop, when set, picks
// the notes to delete instead of republishing.
func (c *consumer) handOffNotes(ctx context.Context, kind gitjobs.SourceKind, target string, drop func(synclease.NoteEntry) bool) {
	failed := false
	for _, k := range gitjobs.SourceKinds {
		log := slog.With(slog.String("target_ulid", target), slog.String("kind", string(k)))
		getCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
		e, found, err := c.lease.pending.Get(getCtx, target, string(k))
		cancel()
		if !found {
			if err != nil {
				log.ErrorContext(ctx, "Failed to read a pending note on release; leaving it for the rekicker", slog.Any("error", err))
				failed = true
			}
			continue
		}
		if err != nil {
			log.ErrorContext(ctx, "Pending note does not decode; leaving it", slog.Any("error", err))
			continue
		}
		if drop != nil && drop(e) {
			log.InfoContext(ctx, "Sync failed for good; deleting the pending note of its kind, the failure index replays the job")
			c.deleteNote(ctx, target, string(k), e.Revision)
			continue
		}
		pubCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
		_, err = c.js.PublishMsg(synclease.RepublishMsg(e.Note), nats.Context(pubCtx))
		cancel()
		if err != nil {
			log.ErrorContext(ctx, "Failed to republish a pending note; leaving it for the rekicker", slog.Any("error", err))
			failed = true
			continue
		}
		c.deleteNote(ctx, target, string(k), e.Revision)
	}
	if failed {
		c.metrics.recordLeaseEvent(ctx, leaseEventReleaseFailed, string(kind))
	}
}

// deleteNote deletes the note for target and kind at rev. A changed revision
// means the note was replaced, by a newer note whoever read rev did not cover,
// or is gone; either way it is left alone. Any other failure may leave the
// note to be republished once more, which costs one redundant sync.
func (c *consumer) deleteNote(ctx context.Context, target, kind string, rev uint64) {
	opCtx, cancel := context.WithTimeout(ctx, leaseOpTimeout)
	defer cancel()
	err := c.lease.pending.DeleteAt(opCtx, target, kind, rev)
	switch {
	case err == nil:
	case errors.Is(err, synclease.ErrRevisionChanged):
		slog.InfoContext(ctx, "Pending note changed or gone since it was read; leaving it",
			slog.String("target_ulid", target), slog.String("kind", kind), slog.Uint64("revision", rev))
	default:
		slog.WarnContext(ctx, "Failed to delete a pending note; it may be republished once more",
			slog.String("target_ulid", target), slog.String("kind", kind), slog.Uint64("revision", rev), slog.Any("error", err))
	}
}

